#!/bin/bash
# Remove all build artifacts (the same things .gitignore lists).
# Always works on the folder this script is in, not the current folder.
# Afterwards CMake Tools reconfigures on the next open or F7.

set -e
cd "$(dirname "$0")"

echo "==== Cleaning: $PWD"

# build: CMake output tree (Debug, Release, bootstrapped images, CMakeCache...).
# out, .vs: Visual Studio's own output and settings folders.
rm -rf ./build ./out ./.vs

# Generated by CMake from version.h.in.
rm -f ./src/version.h

# All images (*.img) in bin and in the example folders (the build, build.sh,
# the VS Code launch configs and the examples' build.sh write them), and the
# copy of lst the build puts in bin.
rm -f ./Smalltalk/Examples/*/*.img ./bin/*.img ./bin/lst ./bin/lst.exe

# Stray compiler and linker output anywhere in the tree.
find . \( -name '*.o' -o -name '*.obj' -o -name '*.pdb' -o -name '*.ilk' -o -name '*.exe' -o -name '*~' \) -type f -delete

echo "Done."
